<script setup lang="ts">
const code=ref(''),mobile=ref(''),appointment=ref<any>(null)
const pending=ref(false),actionPending=ref(false),error=ref(''),notice=ref('')
const change=ref(false),date=ref(''),time=ref(''),slots=ref<string[]>([]),loadingSlots=ref(false)
const {data}=useClinic()
const {data:holidays}=await useFetch<string[]>('/api/public/holidays')
const tz=computed(()=>data.value?.site?.timezone||'Asia/Tehran')
const faStatus=(s:string)=>({confirmed:'تأیید شده',cancelled:'لغو شده',completed:'انجام شده',no_show:'عدم مراجعه'}[s]||s)
async function lookup(){error.value='';notice.value='';pending.value=true;try{appointment.value=await $fetch('/api/public/booking/status',{method:'POST',body:{code:code.value.trim(),mobile:mobile.value.trim()}})}catch(e){appointment.value=null;error.value=humanError(e)}finally{pending.value=false}}
async function cancel(){if(!confirm('آیا از لغو نوبت اطمینان دارید؟'))return;error.value='';actionPending.value=true;try{await $fetch('/api/public/booking/cancel',{method:'POST',body:{code:code.value,mobile:mobile.value}});notice.value='نوبت با موفقیت لغو شد.';await lookup();notice.value='نوبت با موفقیت لغو شد.'}catch(e){error.value=humanError(e)}finally{actionPending.value=false}}
watch(date,async()=>{time.value='';slots.value=[];if(!date.value||!appointment.value)return;loadingSlots.value=true;try{const services=await $fetch<any[]>('/api/public/services');const service=services.find(s=>s.name===appointment.value.service);if(!service){error.value='این خدمت فعال نیست؛ برای جابه‌جایی با مطب تماس بگیرید.';return}slots.value=(await $fetch<{slots:string[]}>('/api/public/availability',{query:{serviceId:service.id,date:date.value}})).slots}catch(e){error.value=humanError(e)}finally{loadingSlots.value=false}})
async function reschedule(){if(!date.value||!time.value)return;error.value='';actionPending.value=true;try{await $fetch('/api/public/booking/reschedule',{method:'POST',body:{code:code.value,mobile:mobile.value,date:date.value,time:time.value}});change.value=false;await lookup();notice.value='زمان نوبت با موفقیت تغییر کرد.'}catch(e){error.value=humanError(e)}finally{actionPending.value=false}}
useSeoMeta({title:'پیگیری، لغو یا تغییر نوبت | دکتر آزاده مهرداد'})
</script>
<template><div class="min-h-[70vh] bg-[#f7faf7]"><section class="bg-[#eff7f0] py-14"><div class="container-wrap max-w-3xl"><span class="eyebrow">مدیریت نوبت شما</span><h1 class="section-title mt-2">پیگیری <span class="text-[#348a77]">نوبت</span></h1><p class="body-muted mt-2">با کد پیگیری و شماره موبایل ثبت‌شده، وضعیت نوبت خود را مشاهده کنید.</p></div></section><div class="container-wrap max-w-3xl py-10 pb-28"><form class="glass-card p-7 sm:p-9" @submit.prevent="lookup"><div class="grid sm:grid-cols-2 gap-5"><div><label class="field-label" for="tracking">کد پیگیری</label><input id="tracking" v-model="code" class="input-field uppercase" dir="ltr" placeholder="مثلاً: A1B2C3D4E5F6" required maxlength="20" /></div><div><label class="field-label" for="track-mobile">شماره موبایل</label><input id="track-mobile" v-model="mobile" class="input-field" dir="ltr" placeholder="09123456789" required inputmode="tel" /></div></div><button class="btn-main mt-7" :disabled="pending"><Icon name="search" :size="18" />{{pending?'در حال جست‌وجو...':'مشاهده وضعیت نوبت'}}</button></form>
<div v-if="error" role="alert" class="mt-5 rounded-xl p-4 bg-red-50 text-red-700 text-xs">{{error}}</div><div v-if="notice" role="status" class="mt-5 rounded-xl p-4 bg-green-50 text-green-700 text-xs">{{notice}}</div>
<div v-if="appointment" class="glass-card p-7 sm:p-9 mt-6 anim-up"><div class="flex flex-wrap gap-3 justify-between items-center mb-7"><h2 class="font-extrabold text-jade-800 text-lg">اطلاعات نوبت</h2><span class="status-pill" :class="`status-${appointment.status}`">{{faStatus(appointment.status)}}</span></div><dl class="grid sm:grid-cols-2 gap-6 text-[13px]"><div><dt class="text-[#839c8f] mb-2">نام مراجعه‌کننده</dt><dd class="font-bold">{{appointment.patientName}}</dd></div><div><dt class="text-[#839c8f] mb-2">خدمت</dt><dd class="font-bold">{{appointment.service}}</dd></div><div><dt class="text-[#839c8f] mb-2">تاریخ مراجعه</dt><dd class="font-bold">{{faDate(appointment.date,tz)}}</dd></div><div><dt class="text-[#839c8f] mb-2">ساعت مراجعه</dt><dd class="font-bold" dir="ltr">{{appointment.time}}</dd></div></dl>
<div v-if="appointment.canModify" class="mt-8 pt-6 border-t border-[#e8f0e9]"><p class="text-xs text-[#779185] mb-4">تا {{faNumber(appointment.cancellationHours)}} ساعت پیش از نوبت امکان تغییر یا لغو وجود دارد.</p><div class="flex flex-wrap gap-3"><button class="btn-light" :disabled="actionPending" @click="change=!change,error=''">تغییر تاریخ و ساعت</button><button class="rounded-xl border border-rose-200 text-rose-700 text-xs font-bold px-5 py-3 hover:bg-rose-50" :disabled="actionPending" @click="cancel">لغو نوبت</button></div><div v-if="change" class="mt-7 border-t border-[#e6eee7] pt-6"><h3 class="font-bold text-sm mb-4">انتخاب زمان جدید</h3><div class="grid sm:grid-cols-2 gap-5"><JalaliCalendar v-model="date" :timezone="tz" :horizon="data?.site?.booking_horizon_days" :blocked-dates="holidays||[]" :working-hours="data?.site?.working_hours" /><div><p class="field-label">ساعت آزاد</p><p v-if="loadingSlots" class="text-xs text-[#78988a]">در حال دریافت ساعت‌ها...</p><div v-else-if="slots.length" class="grid grid-cols-3 gap-2"><button v-for="slot in slots" :key="slot" type="button" class="border rounded-xl p-3 text-xs" :class="time===slot?'bg-jade-700 text-white':'bg-white border-[#dcebe1]'" @click="time=slot">{{slot}}</button></div><p v-else class="text-xs text-[#879c8f] leading-7">{{date?'ساعتی برای این روز وجود ندارد.':'لطفاً ابتدا روزی را انتخاب کنید.'}}</p></div></div><button :disabled="!date||!time||actionPending" class="btn-main mt-5" @click="reschedule">ثبت زمان جدید</button></div></div><p v-else-if="appointment.status==='confirmed'" class="mt-7 text-[12px] bg-[#fff8e9] text-[#957743] rounded-xl p-4">مهلت تغییر و لغو آنلاین پایان یافته است؛ لطفاً با مطب تماس بگیرید.</p></div>
</div></div></template>
